178	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
179	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
180	func parseNexusURL(registryURL string) (host, repoName string, err error) {
181		raw := registryURL
182		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
183			raw = "https://" + raw
184		}
185		u, err := url.Parse(raw)
186		if err != nil {
187			return "", "", err
188		}
189		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
190		// Expected: ["repository", "<repoName>", ...]
191		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
192			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
193		}
