140			focusedField:      brFieldRepo,
141			filterInput:       fi,
142			tagSortCol:        tagSortByName,
143			tagSortDesc:       false,
144			tagTable:          tt,
145			spinner:           sp,
146			scanCache:         make(map[string]cache.ImageScanEntry),
147			scanningTags:      make(map[string]bool),
148			state:             browserStateResolving,
149		}
150		b.resizeInputs()
151		b.resizeTagTable()
152	
153		if len(registries) == 0 {
154			b.state = browserStateInput
155			return b, nil
156		}
157	
158		cmds := make([]tea.Cmd, 0, len(registries)+1)
159		for _, reg := range registries {
160			cmds = append(cmds, detectRegistryGroupCmd(reg, ""))
161		}
162		cmds = append(cmds, sp.Tick)
163		return b, tea.Batch(cmds...)
164	}
