229	func (b *RegistryBrowser) resizeTagTable() {
230		b.tagTable.SetHeight(max(b.height, 1))
231	
232		// b.width is already the viewport content width (full width - 2 borders).
233		// Subtract only the cell padding (numCols × 2) so column widths sum exactly to `available`.
234		const numCols = 7
235		available := max(b.width-numCols*2, 10)
236		fixedReg := 20
237		fixedUpdated := 16
238		fixedC, fixedH, fixedM := 4, 4, 4
239		fixedSum := fixedReg + fixedUpdated + fixedC + fixedH + fixedM
240		flexTag := max(available-fixedSum-4, 8) // reserve 4 for last col minimum
241	
242		cols := b.tagTable.Columns()
243		if len(cols) == numCols {
244			cols[0].Width = fixedReg
245			cols[1].Width = flexTag
246			cols[2].Width = fixedUpdated
247			cols[3].Width = fixedC
248			cols[4].Width = fixedH
249			cols[5].Width = fixedM
250			// Last column absorbs leftover so sum(col_widths) == available exactly.
251			cols[6].Width = available - fixedReg - flexTag - fixedUpdated - fixedC - fixedH - fixedM
252			b.tagTable.SetColumns(cols)
253		}
254	
255		// Force the Selected row style to span the viewport content width so the selected
256		// background extends to the right border, even when row content visually differs
257		// from the calculated width (e.g. Nerd Font icon width discrepancies). See workspaces fix.
258		styles := theme.DefaultTableStyles()
259		styles.Selected = styles.Selected.Width(b.width)
260		b.tagTable.SetStyles(styles)
261	}
