470	func (b *RegistryBrowser) cycleSortTags() {
471		if b.tagSortCol == tagSortByName && !b.tagSortDesc {
472			b.tagSortDesc = true
473		} else if b.tagSortCol == tagSortByName && b.tagSortDesc {
474			b.tagSortCol = tagSortByUpdated
475			b.tagSortDesc = false
476		} else if b.tagSortCol == tagSortByUpdated && !b.tagSortDesc {
477			b.tagSortDesc = true
478		} else {
479			b.tagSortCol = tagSortByName
480			b.tagSortDesc = false
481		}
482		b.rebuildTagTable()
483	}
484	
485	func (b *RegistryBrowser) cycleRegistryFilter() {
486		seen := make(map[string]bool)
487		var urls []string
488		for _, t := range b.tags {
489			if !seen[t.RegistryURL] {
490				seen[t.RegistryURL] = true
491				urls = append(urls, t.RegistryURL)
492			}
493		}
494		if len(urls) <= 1 {
495			b.registryFilter = ""
496			b.rebuildTagTable()
497			return
498		}
499		if b.registryFilter == "" {
500			b.registryFilter = urls[0]
501		} else {
502			found := false
503			for i, u := range urls {
504				if u == b.registryFilter {
505					next := (i + 1) % (len(urls) + 1)
506					if next == len(urls) {
507						b.registryFilter = ""
508					} else {
509						b.registryFilter = urls[next]
510					}
511					found = true
512					break
513				}
514			}
515			if !found {
516				b.registryFilter = ""
517			}
518		}
519		b.rebuildTagTable()
520	}
