702	// filteredSortedMultiTags returns tags after applying registry filter, text filter, and sort.
703	func (b *RegistryBrowser) filteredSortedMultiTags() []MultiRegistryTag {
704		query := strings.ToLower(b.filterInput.Value())
705		var result []MultiRegistryTag
706		for _, t := range b.tags {
707			if b.registryFilter != "" && t.RegistryURL != b.registryFilter {
708				continue
709			}
710			if query != "" && !strings.Contains(strings.ToLower(t.Tag), query) &&
711				!strings.Contains(strings.ToLower(t.Repo), query) {
712				continue
713			}
714			result = append(result, t)
715		}
716	
717		sortCol := b.tagSortCol
718		sortDesc := b.tagSortDesc
719		sort.SliceStable(result, func(i, j int) bool {
720			var less bool
721			switch sortCol {
722			case tagSortByUpdated:
723				less = result[i].UpdatedAt.After(result[j].UpdatedAt)
724			default:
725				less = strings.ToLower(result[i].Tag) < strings.ToLower(result[j].Tag)
726			}
727			if sortDesc {
728				return !less
729			}
730			return less
731		})
732		return result
733	}
734	
735	// rebuildTagTable rebuilds the results table rows with current filter/sort/CVE data.
736	func (b *RegistryBrowser) rebuildTagTable() {
737		displayed := b.filteredSortedMultiTags()
738		rows := make([]table.Row, len(displayed))
739		for i, t := range displayed {
740			imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
741	
742			registryLabel := t.Alias
743			if registryLabel == "" {
744				registryLabel = t.RegistryURL
745			}
746	
747			updated := "-"
748			if !t.UpdatedAt.IsZero() {
749				updated = theme.TimeAgo(t.UpdatedAt)
750			}
751	
752			crit, high, med, low := "-", "-", "-", "-"
753			if b.scanningTags[imageName] {
754				frame := spinner.Dot.Frames[b.tagScanSpinnerIdx%len(spinner.Dot.Frames)]
755				crit, high, med, low = frame, frame, frame, frame
756			} else if entry, ok := b.scanCache[imageName]; ok {
757				crit = fmt.Sprintf("%d", entry.Critical)
758				high = fmt.Sprintf("%d", entry.High)
759				med = fmt.Sprintf("%d", entry.Medium)
760				low = fmt.Sprintf("%d", entry.Low)
761			}
762	
763			rows[i] = table.Row{registryLabel, t.Tag, updated, crit, high, med, low}
764		}
765	
766		cols := b.tagTable.Columns()
767		if len(cols) == 7 {
768			cols[1].Title = "Tag"
769			cols[2].Title = "Updated"
770			switch b.tagSortCol {
771			case tagSortByName:
772				arrow := " ▲"
773				if b.tagSortDesc {
774					arrow = " ▼"
775				}
776				cols[1].Title = "Tag" + arrow
777			case tagSortByUpdated:
778				arrow := " ▲"
779				if b.tagSortDesc {
780					arrow = " ▼"
781				}
782				cols[2].Title = "Updated" + arrow
783			}
784			b.tagTable.SetColumns(cols)
785		}
786	
787		b.tagTable.SetRows(rows)
788		b.resizeTagTable()
789	}
