810	func (b *RegistryBrowser) viewInput() string {
811		var sb strings.Builder
812	
813		sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
814		sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
815		sb.WriteString("\n\n")
816	
817		if len(b.entries) > 0 {
818			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
819			var currentGroup string
820			for i, entry := range b.entries {
821				if entry.ParentAlias != "" && entry.ParentAlias != currentGroup {
822					if currentGroup != "" {
823						sb.WriteString("\n")
824					}
825					currentGroup = entry.ParentAlias
826					sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render(currentGroup+":") + "\n")
827				} else if entry.ParentAlias == "" && currentGroup != "" {
828					currentGroup = ""
829					sb.WriteString("\n")
830				}
831				label := entry.Alias
832				if entry.ParentAlias != "" {
833					label = "  " + entry.Alias // visual indent for group members
834				}
835				checked := b.selectedRegs[entry.URL]
836				focused := b.focusedField == b.brFieldReg(i)
837				sb.WriteString(theme.RenderCheckbox(checked, label, focused))
838				if i < len(b.entries)-1 {
839					sb.WriteString("\n")
840				}
841			}
842			sb.WriteString("\n\n")
843		}
844	
845		sb.WriteString("  ")
846		sb.WriteString(theme.RenderButton("Browse Tags", b.focusedField == b.brFieldSubmit(), "primary"))
847	
848		return sb.String()
849	}
850	
851	func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
852		var labelStr string
853		if b.focusedField == fieldIdx {
854			labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
855		} else {
856			labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
857		}
858		return labelStr + "\n  " + value
859	}
860	
861	func (b *RegistryBrowser) viewTags() string {
862		displayed := b.filteredSortedMultiTags()
863		if len(displayed) == 0 {
864			if b.pendingSearches > 0 {
865				return theme.EmptyLineBg(b.width) + "\n" +
866					theme.SpinnerMessage(b.spinner.View(), "Searching registries...")
867			}
868			return theme.DimStyle.Render("  No tags found")
869		}
870		return b.tagTable.View()
871	}
872	
873	// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
874	func (b *RegistryBrowser) FilterIsVisible() bool {
875		return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || b.registryFilter != "")
876	}
877	
878	// FilterBarView renders the filter bar (2 lines) for display in the footer.
879	func (b *RegistryBrowser) FilterBarView(width int) string {
880		borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
881	
882		var left string
883		if b.filterActive {
884			left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
885		} else if b.filterInput.Value() != "" {
886			left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
887		} else {
888			left = theme.DimStyle.Render("/ filter…")
889		}
890	
891		if b.registryFilter != "" {
892			left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
893		}
894	
895		inner := theme.Bg(" ") + left
896		paddedInner := theme.PadWithBg(inner, width-2)
897		contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
898		bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
899		return contentLine + "\n" + bottomBorder
900	}
901	
902	func (b *RegistryBrowser) viewStatus() string {
903		var label string
904		switch b.operation {
905		case "pull":
906			label = "Pulling " + b.imageName + "..."
907		default:
908			label = "Working..."
909		}
910		return theme.EmptyLineBg(b.width) + "\n" +
911			theme.SpinnerMessage(b.spinner.View(), label)
912	}
