333	
334	// registryAPIURL converts a user-specified registry URL into a v2 API base URL.
335	func registryAPIURL(registryURL string) string {
336		base := strings.TrimSuffix(registryURL, "/")
337		lower := strings.ToLower(base)
338		switch lower {
339		case "docker.io", "registry-1.docker.io":
340			return "https://registry-1.docker.io"
341		}
342		if !strings.HasPrefix(lower, "http://") && !strings.HasPrefix(lower, "https://") {
343			return "https://" + base
344		}
345		return base
346	}
